      "במועצה האזורית שער הנגב שימש עומר כמנהל המחשוב. הוא מילא את תפקידו במקצועיות, בכישרון ובסבלנות אין קץ. הוא טיפל בכל עניין במאור פנים ובחיוך, והיה כתובת זמינה, רגועה וטובה לכל מי שנזקק לעזרתו.",
