      "בן מסור להוריו ואח אוהב ותומך. שחר כיבד את הוריו והפיץ בבית אור ושמחה. עם שני אחיו טיפח קשר חם וקרוב. שרון אחיו תיאר אח גדול במלוא מובן המילה שעמד לצידו בכל הצמתים החשובים בחיים, דאג לו ושמר עליו.",
