      "בנם של מיכל ודורון. נולד ביום ד' בטבת תשנ\"ח (2.1.1998) בקיבוץ כפר עזה. אח גדול לגלי.",
      "גיא גדל בכפר עזה ב״קבוצת אש״ל״ של בני גילו. ביחד עם חבריו לקבוצה למד במוסדות החינוכיים של מועצה אזורית שער הנגב מכיתה א׳ ועד י״ב.",
