      "אחרי שסיים את הטירונות, החל את ההכשרה ביחידה, ושם הכיר את נועה, שהייתה לחברתו. \"ביום הראשון, כשרק הגענו ליחידה, הוא כבר שאל את המפקדות מתי אפשר לצאת לקורס קצינים\".",
