    "fullStory": [
      "בנם-בכורם של בתיה ויהודה. נולד ביום כ\"ג באדר א' תשכ\"ה (25.2.1965) בקיבוץ כפר עזה. למד שנה אחת בקיבוצו וסיים את חוק לימודיו היסודיים והתיכוניים בבית הספר בשער הנגב, במגמת אלקטרוניקה. כך זוכרת אותו מורתו: \"אני מגלה שלפני ירון התלמיד ישנו ירון - ילד-נער בעל תכונות אנוש נפלאות, מלא כבוד לזולת, וראשית כול כלפי הוריו: מצוות כיבוד אב ואם נראית כמושרשת בעצמותיו. שופע אהבה שמתבטאת בחיוך שבקצות השפתים, בנצנוץ בעיניים - אליכם ההורים... ומעבר לכל אלה ישנו ירון החבר, הרע - האהוב על חבריו... תמיד בפיו מלה טובה פה, חיוך שם, הלצה קטנה פה, התייחסות רצינית שם. בשקט שלו נכון לסייע, לעזור ולתמוך\". כבר בתור תינוק התבלט באופיו הנוח והשקט ותכונות אלו ליוו אותו.",
      "בחברת הילדים שאך זה הוקמה בכפר עזה, חברה שחיפשה את דרכה, הורגשה מעורבותו של ירון במתן כיוון ההתפתחות הרצוי בשל רגש האכפתיות החזק שהיה טמון בו. ירון היה ספורטאי מחונן, הרבה לעסוק בספורט הצלילה והיה חבר בנבחרת הכדורסל של שער הנגב. כאשר הגיע זמנו להשתלב בעבודות הקיבוץ, הצטרף ירון לענף הרפת. בזכות הבגרות והאחריות שגילה רכש לו עד מהרה מקום של כבוד והערכה בצוות הענף. על-נקלה השתלט על מלאכת החליבה והטיפול במכונות החקלאיות והיה גאה במגפיו המכוסים בוץ ובכפות ידיו השחורות משמן מכונות. כבני משקים אחרים, התנדב ירון עם סיום לימודיו לפני גיוסו לצה\"ל לשנת שירות שבמהלכה הדריך קבוצת נוער בחדרה במסגרת 'הנוער העובד והלומד'.",
      "ירון גויס לצה\"ל בסוף אוקטובר 1984 והתנדב לשרת בחיל הצנחנים. לאחר הטירונות סיים בהצלחה קורס מ\"כים וכהוקרה על כך נשאר בגדוד והיה לאחד המפקדים בו. ירון נתמנה לסמל מחלקה וקיבל תחת פיקודו את מחלקת המכ\"צים ובה בלטו חריצותו ורצונו להגיע להישגים גבוהים. כמפקד עשה ירון מעבר למה שדרש תפקידו ועל כך זכה להערכת מפקדיו ופקודיו.",
      "ביום י\"ח בכסלו תשמ\"ו (1.12.1985) נפל ירון בעת מילוי תפקידו בתאונת-דרכים בכביש בית שאן - בית זרע והובא למנוחות בחלקה הצבאית בבית-העלמין שבקיבוצו. לאחר נופלו הועלה לדרגת סמל. ירון השאיר אחריו הורים, אח - דורון ושלוש אחיות - אורית, רוית ושרון.",
      "בדברי ההספד לזכרו אמר מפקדו: \"כולנו נזכור אותך כטיפוס חייכן אשר לקח את הכול בקלות, אך התמודד עם הבעיות בצורה מבוגרת למופת. מפקד אשר לא בחל להתמודד עם מפקדיו הממונים עליו, על-מנת לדאוג לחייל הקטן... לא רק תכונות של מפקד היו בך - מקצועיות, שקידה, חריצות, עוז רוח וכושר פיקודי - אלא היית אדם למופת\". במכתב התנחומים למשפחה השכולה כתב מפקד יחידתו, בין השאר: \"ירון הגיע לגדוד במסגרת מסלול בני המשקים... הוא דאג רבות לחייליו וחשוב היה לו שירגישו בטוב ולא יחסר להם מאום. ירון חשב רבות על המשך דרכו כקצין כדי לתרום בכך מעבר לחובתו. רצונו זה, נאמנותו לתפקיד, הרצינות והאחריות שגילה היו המאפיינים את דמותו\". משפחתו הוציאה לאור חוברת לזכרו ובה תולדות חייו ודברים לזכרו. אחותו, הצעירה ממנו בשנתיים וחצי, עשתה עליו סרט דוקומנטרי והגישה אותו כעבודת סיום במסגרת לימודי הווידאו שלה במכללת שער הנגב. ביום הזיכרון העשירי לנפילת ירון, כתבה אחותו שיר לזכרו. השיר הולחן על-ידי חבר הקיבוץ ראובן דומן ומושר בפיה של מיכל ויינר."
    ],
