    "isPreviousYears": true,
    "page": "people/asaf_rabinovitz/",
    "gender": "male",
    "fullStory": [
      "בן גרשון ואליה. נולד ביום כ' באדר תש\"ב (9.3.1942) בחיפה. למד בבית-הספר שבקיבוץ רוחמה וסיים את לימודיו היסודיים בו; לאחר-מכן המשיך במוסד החינוכי של הקיבוץ. כתלמיד הראה את רצינותו, אחריותו ואת השקט שבו. הוא שנא את הקולניות והראוותנות והיה מביע את דבריו מתוך עצמאיות. היה אדם שקט ומופנם, אך מי שהכיר אותו ידע שהיה בו עולם פנימי עשיר ועמוק. ישר-דרך היה, פשוט בהליכותיו ותמים ולא היה נוטה להתחבר לזולת מתוך טפיחה על השכם ומתוך ברכה קולנית.",
      "עסק בחקלאות ובשדות-הפלחה התחיל לרכוש את אמון חבריו-לעבודה ואת הערכת חברי-המשק בכלל. באוגוסט 1960 גויס לצה\"ל ולאחר שגמר את שירותו הסדיר היה נקרא למילואים מפעם לפעם.",
      "לדגל נקרא שוב לשרת במלחמת ששת הימים, וביום החמישי לקרבות, א' בסיון תשכ״ז (9.6.1967), נפל בקרב שנערך בראס-סודר שבסיני. על שירותו המצוין הועלה אסף לדרגת סרן לאחר מותו.",
      "הובא לקבורה בבית-הקברות הצבאי לשעת-חירום בבארי והועבר לאחר-מכן למנוחת-עולמים בבית-הקברות ברוחמה. ב\"שלושים\" לנפלו הוציא הקיבוץ רוחמה עלון לזכרו. חוברת לזכרו הנושאת את שמו הופיעה. בחוברת \"53 מהם\", שהוציא הקיבוץ הארצי לזכר חבריו שנפלו במערכה, הובאו תולדותיו."
    ],
