    "page": "people/zeev_lavi/",
    "gender": "male",
    "fullStory": [
      "בן אברהם ובתיה. נולד ביום כ\"ג באב תש\"ח (28.8.1948), בקיבוץ רוחמה. גדל והתחנך בקיבוץ וסיים שם את לימודיו היסודיים והתיכוניים. הוא היה אדם מלא מרץ וכמיהה ליצירה. תמיד רצה לעשות, לפעול, ליצור. הוא היה הראשון לעושים ולנושאים בעול, במסיבות, בשיחות-רעים ובכל פעולה שהצריכה התמסרות. הוא אהב אנשים, שמח לתת להם מעצמו, להשתלב ברוח-חפצה בעשייה משותפת של הכלל. זה היה סוד-שלמותו, סוד-שמחתו.",
      "זאביק גויס לצה\"ל בינואר 1968 והצטרף לנח\"ל. אור ליום ט' בתשרי תש\"ל (20.9.1969), נפל בהיתקלות עם מחבלים. הובא למנוחת-עולמים בבית-הקברות בקיבוצו.",
      "חבר סיפר עליו לאחר שנפל: \"זאב היה אדם מאושר, כיון שתמיד פעל לפי מצפונו והכרתו. בעיני היה איש המצפון הכן - ולכן הייתי תמיד כה גאה בו. בשיחות האחרונות עמו נהניתי תמיד לראות אותו מתלבט בבעיות מצפוניות שאחרים לא שמו לב אליהן. נהניתי לעקוב אחר התבגרותו. אהבתי כשבלהט הוויכוח היה משמיע דברים שמנסיוני ידעתי כי בעוד שנה יודה בטעותו. הכנות שבה יודע היה להודות בשגיאותיו, הייתה אצלו דבר נפלא, שכמעט אין למצוא באחרים\".",
      "בחוברת \"זאביק שלנו\", שיצאה לאור לאחר נפלו, כתב עליו מפקד יחידתו: \"זאביק, אותו נער אשר את פגישתנו הראשונה ערכנו בצבא, היה תמיד הנער בעל הרוח התוססת, אשר מעולם לא נח ולא שקט, בהציבו לעצמו אתגרים ובהגיעו אליהם. הוא שאף ליותר. זאביק התחיל ביחידתנו כחייל וסיים את המחזור בהצטיינות והפך להיות מפקד-כיתה מצטיין. כמרכז גרעין יכול היה זאביק בסוף המחזור לשוב יחד עם בני הגרעין לאתגר שהציב לו בראשית דרכו - התיישבות בקיבוץ כרם-שלום, אולם לפני הגשימו בכרם-שלום החליט זאביק שאת שירותו הצבאי יתרום בפיקוד בצה\"ל. אופייני לזאביק שלא הסתפק בפיקוד של כיתה ושאף להיות קצין ביחידה. בטוחני שאם היה ממשיך בדרך שבה החליט ללכת ודאי היה הוא ביחידתנו קצין מעולה\"."
    ],
