    "isPreviousYears": true,
    "page": "people/yuri_haranash/",
    "gender": "male",
    "fullStory": [
      "יורי, בן חנה ואהרון, נולד ביום א' בחשון תש\"י (24.10.1949) בקיבוץ רוחמה ולמד בבית-הספר היסודי ובבית-הספר התיכון בקיבוצו. יורי היה תלמיד מוכשר, מן הראשונים שידעו קרוא ואף נהג לדבר בניב ספרותי-ציורי. משגדל הפך חובב-ספורט, אך גם חובב ספר היה, והקדיש הרבה משעות הפנאי שלו לקריאה, ולא פעם בילדותו הזדהה עם עלילות הספרים שקרא. בעודו ילד היה מסתגר ומרבה להתבודד עם ספריו, אך משנעשה נער הפך חברותי ומוכן לעזור לזולת, פעיל בחברה, בעל הומור ואוהב מעשה קונדס. תמיד היה רציני בגישתו לחיים, גם אם נהג לעתים בבדיחות-דעת. מטבעו היה אופטימי וסלחן ביחסו אל הבריות, התייחס בהבנה לחולשות אנוש אך התלהב מתכונות חיוביות שמצא באנשים. נעים שיחה היה ורחב אופקים, ולפיכך היה אהוד על חניכיו כששימש כמדריך-נוער ואהוב על פקודיו כשנהיה קצין בצה\"ל. תמיר, יפה-תואר, בעל מבט ישיר וחייכני היה יורי. בילדותו נסע לברזיל עם הוריו, שעשו שם בשליחות, וחזר לקיבוצו כדי לסיים את לימודיו. מנעוריו היה קשור בכל נימי-נפשו לקיבוצו.",
      "יורי גויס לצה\"ל בתחילת נובמבר 1968 והוצב לחיל-ההנדסה. לאחר סיום הטירונות ולאחר שהשתלם בקורס מ\"כים עבר קורס מש\"קי-הנדסה וקורס צניחה. הוא מילא בהצלחה את תפקידו ולאחר תקופת שירות נשלח להשתלם בקורס קצינים ובקורס קציני-הנדסה. אחרי-כן הוצב בתפקיד קצין-מודיעין והועלה לדרגת סרן. הוא היה קצין מסור ואחראי למופת, בעל יזמה ודייקן בביצוע כל המשימות שהוטלו עליו. לדברי מפקדיו, יורי חי את תפקידו, היה מעמודי התווך של הגדוד, השרה על אנשיו ביטחון רב והיה מפקד וחבר כאחד.",
      "לאחר שסיים את שירותו בצה\"ל לא היסס כלל בבחירת דרכו וחזר להקים את ביתו בקיבוץ. ביום ט\"ו בכסלו תשל\"ד (10.12.1973) נפטר יורי לאחר שנפצע בעת מילוי תפקידו והובא למנוחת-עולמים בבית-העלמין האזרחי של קיבוץ רוחמה. השאיר אחריו אישה, הורים ואחות.",
      "קיבוצו הוציא לאור חוברת לזכרו, מדברי חברים על דמותו ונאמר בה: \"יורי היה עדין-נפש. במצבים הגרועים ביותר הוא השכיל לחשוב על בעיות שברומו של עולם והצליח לעורר אצל אחרים מחשבה ורגשנות;\" \"הוא היה תמים ונהדר, מתרגש מן היפה ומוצא אותו בירק ובפרחים. הוא אהב את השלמות שבעשייה, סלד מן המליצה ומדברים הנאמרים אחרי המוות\"."
    ],
